def load_admission_controls(gates):
    payload=base64.b85decode(ADMISSION_CONTROL_B85)
    gates.check('Pass8_admission_control_SHA',digest(payload),ADMISSION_CONTROL_SHA256)
    gates.require()
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        gates.check('Pass8_control_CRC',archive.testzip(),None)
        gates.check('Pass8_control_unique_members',len(archive.namelist()),len(set(archive.namelist())))
        blobs={n:archive.read(n) for n in archive.namelist()}
    manifest=json.loads(blobs['file_manifest.json'])
    gates.check('Pass8_control_exact_member_set',set(blobs),{r['file'] for r in manifest}|{'file_manifest.json'})
    for item in manifest:
        b=blobs[item['file']]
        gates.check('Pass8_control_size:'+item['file'],len(b),item['bytes'])
        gates.check('Pass8_control_SHA:'+item['file'],digest(b),item['sha256'])
    provenance=json.loads(blobs['control_provenance.json'])
    gates.check('reviewed_Pass8_parent_SHA',provenance['parent_sha256'],'4c1488eec15340d286b407ac6ae8d2bf5c90a4619da4ca3b27c9144f379049de')
    gates.check('exact_baseline_control_book',blobs['incumbent_frozen_book.json']==base64.b85decode(BASELINE_B85),True)
    registry=[dict(sid=sid,risk_fraction=risk_rate(sid),trades=sum(r['sid']==sid for r in json.loads(blobs['incumbent_frozen_book.json'])))
              for sid in sorted({r['sid'] for r in json.loads(blobs['incumbent_frozen_book.json'])})]
    check_rows(gates,'exact_reviewed_P31_registry',registry,read_csv_bytes(blobs['incumbent_registry.csv']))
    gates.require()
    return blobs

def gate_original_admission(outputs,controls,gates):
    names=['portfolio_summary.csv','scenario_plan.csv','candidate_cutoff_ledgers.csv','candidate_gate_audit.csv',
           'open_at_portfolio_cutoff.csv','entry_overlap.csv','equity_events.csv','monthly_results.csv',
           'period_results.csv','rolling_windows.csv','rolling_summary.csv','weak_window_attribution.csv']
    for name in names:
        actual=outputs[name];reference=read_csv_bytes(controls[name]);converted=[];schema=True
        for row,ref in zip(actual,reference):
            schema &= set(row)==set(ref)
            record={}
            for k,value in row.items():
                raw=ref.get(k)
                if raw is None or raw=='':target='' if raw=='' and isinstance(value,str) else None
                elif isinstance(value,bool):target=raw=='True'
                elif isinstance(value,int):target=int(raw)
                elif isinstance(value,float):target=float(raw)
                else:target=raw
                record[k]=target
            converted.append(record)
        tag='reviewed_Pass8_all_baseline_original:'+name
        gates.check(tag+':row_count',len(actual),len(reference))
        gates.check(tag+':all_row_schemas',schema,True)
        # Complete typed row hashes gate every field/order without millions of
        # repetitive diagnostic rows in a standalone service.
        gates.check(tag+':complete_typed_rows_SHA',digest(json.dumps(actual,sort_keys=True,separators=(',',':'),allow_nan=False).encode()),
                    digest(json.dumps(converted,sort_keys=True,separators=(',',':'),allow_nan=False).encode()))
    gates.check('reviewed_Pass8_scenarios_before_quality',len(outputs['portfolio_summary.csv']),7)
    gates.require()

def build_cutoff_source(hourly,daily,gates):
    prefix=[b for b in hourly if b[0]+HOUR<=CUTOFF]
    dayprefix=[b for b in daily if b[5]<=CUTOFF]
    original,_,_,_=identify_original(prefix)
    original=[i for i in original if prefix[i][0]+HOUR<CUTOFF]
    indicators=daily_features(dayprefix)
    contexts=[dict(signal_index=i,signal=stamp(prefix[i][0]),
                   **context_for_signal(dayprefix,indicators,prefix[i][0]+HOUR)) for i in original]
    filtered=[r['signal_index'] for r in contexts if quality_eligible(r)]
    membership={RULES[0]['config_id']:original,RULES[1]['config_id']:filtered}
    gates.check('cutoff_H1_completed_prefix_count',len(prefix),137624)
    gates.check('cutoff_H1_last_open',stamp(prefix[-1][0]),'2026-09-18T20:00:00Z')
    gates.check('cutoff_only_completed_H1',all(b[0]+HOUR<=CUTOFF for b in prefix),True)
    gates.check('cutoff_only_completed_D1',all(b[5]<=CUTOFF for b in dayprefix),True)
    gates.check('cutoff_daily_asof_no_future',all(date(r['daily_end'])<=date(r['decision'])<=CUTOFF for r in contexts if r['daily_end']),True)
    # Indicators calculated from only completed D1 source must exactly match
    # causal values from the previously confirmed complete historical source.
    full_indicators=daily_features(daily)
    full_contexts=[dict(signal_index=i,signal=stamp(hourly[i][0]),**context_for_signal(daily,full_indicators,hourly[i][0]+HOUR)) for i in original]
    gates.check('cutoff_daily_context_exact_causal_prefix',contexts,full_contexts)
    gates.require()
    for r in contexts:r['passes_quality']=int(quality_eligible(r))
    raw=[dict(config_id=rule['config_id'],strategy_id=rule['strategy_id'],role=rule['role'],signal_index=i,
              signal=stamp(prefix[i][0]),entry=stamp(prefix[i][0]+HOUR)) for rule in RULES for i in membership[rule['config_id']]]
    return dict(hourly=prefix,daily=dayprefix,membership=membership,contexts=contexts,memberships=raw,last_invalid=[],last_blocked=[])

def cutoff_candidates(source,rule,model,cost,full_rows,gates):
    prefix=source['hourly'];indices=source['membership'][rule['config_id']]
    paths={i:isolated_path(prefix,i,model) for i in indices}
    accepted,invalid,blocked=execute_p0(rule,indices,paths,model,cost)
    expected=[{k:r[k] for k in ROW_FIELDS} for r in full_rows if r['config_id']==rule['config_id']
              and r['execution_model']==model and r['cost_ticks']==cost and date(r['entry'])<CUTOFF]
    for r in expected:
        if r['exit'] is None or date(r['exit'])>CUTOFF:
            r.update(exit_index=None,exit=None,exit_price=None,reason='OPEN_AT_DATA_END',r=None)
    name=f'CUTOFF:{rule["role"]}:{model}:{cost}'
    gates.check(name+':full_censored_fields',accepted,expected)
    gates.check(name+':no_future_exit',all(r['exit'] is None or date(r['exit'])<=CUTOFF for r in accepted),True)
    gates.check(name+':open_R_blank',all(r['r'] is None for r in accepted if r['exit'] is None),True)
    gates.check(name+':raw_membership_partition',len(accepted)+len(invalid)+len(blocked),len(indices))
    gates.require()
    book=[dict(sid=rule['strategy_id'],pair='EUR_CHF',side='SELL',tf='H1',rr=rule['rr'],signal=r['signal'],entry=r['entry'],exit=r['exit'],r=r['r']) for r in accepted]
    audit=[dict(signal_index=r['signal_index'],signal=r['signal'],entry=r['entry'],status='ACCEPTED_OPEN' if r['exit'] is None else 'ACCEPTED_CLOSED') for r in accepted]
    audit.extend(dict(signal_index=r['signal_index'],signal=stamp(prefix[r['signal_index']][0]),entry=paths[r['signal_index']]['entry'],status=r['reason']) for r in invalid)
    audit.extend(dict(signal_index=r['signal_index'],signal=stamp(prefix[r['signal_index']][0]),entry=paths[r['signal_index']]['entry'],status='BLOCKED_P0') for r in blocked)
    source['last_invalid']=invalid;source['last_blocked']=blocked
    return book,accepted,sorted(audit,key=lambda r:r['signal_index']),len(prefix),len(blocked)

def resizing_rows(sim,base,tag,gates):
    new={(e['source_record_index'],e['event']):e for e in sim['events'] if e['source']=='INCUMBENT'}
    old={(e['source_record_index'],e['event']):e for e in base['events']}
    gates.check(tag['scenario']+':same_incumbent_events',set(new),set(old))
    rows=[];unchanged=True
    for i,trade in enumerate(base['book']):
        en,ex=new[(i,'ENTRY')],new[(i,'EXIT')];ben,bex=old[(i,'ENTRY')],old[(i,'EXIT')]
        for n,b in [(en,ben),(ex,bex)]:
            unchanged &= all(n[k]==b[k] for k in ('time','event','sid','pair','side','source_record_index','signal','entry','exit','r','risk_fraction'))
        rows.append(dict(tag,incumbent_record_index=i,sid=trade['sid'],pair=trade['pair'],entry=trade['entry'],exit=trade['exit'],r=trade['r'],
                         baseline_risk_cash=ben['risk_cash'],scenario_risk_cash=en['risk_cash'],risk_cash_delta=en['risk_cash']-ben['risk_cash'],
                         baseline_pnl_cash=bex['pnl_cash'],scenario_pnl_cash=ex['pnl_cash'],pnl_cash_delta=ex['pnl_cash']-bex['pnl_cash']))
    gates.check(tag['scenario']+':incumbent_identity_risk_rates_unchanged',unchanged,True)
    delta=sum(r['pnl_cash_delta'] for r in rows)
    total=sum(e['pnl_cash'] for e in new.values())-sum(e['pnl_cash'] for e in old.values())
    gates.check(tag['scenario']+':full_resizing_cash_identity',equal_price(delta,total),True)
    gates.require()
    return rows

def event_ties(sim,tag):
    bytime=defaultdict(list)
    for e in sim['events']:bytime[e['time']].append(e)
    return [dict(tag,time=time,events_at_timestamp=len(records),tie_rank=rank,
                 event=e['event'],sid=e['sid'],source_record_index=e['source_record_index'],
                 event_sequence=e['event_sequence'],balance_before=e['balance_before'],risk_cash=e['risk_cash'])
            for time,records in bytime.items() if len(records)>1 for rank,e in enumerate(records,1)]

def add_comparison_reports(outputs,gates):
    metrics=['balance_from_100','common_window_cagr_pct','max_closed_dd_pct','max_open_risk_floor_dd_pct',
             'max_positions','max_open_risk_pct','max_gross_EUR_risk_pct','max_gross_CHF_risk_pct',
             'candidate_closed_trades','candidate_closed_r','worst_12m_return_pct','worst_24m_return_pct','worst_36m_return_pct']
    for model in MODELS:
        for cost in COSTS:
            a,b=[next(r for r in outputs['portfolio_summary.csv'] if r['role']==rule['role'] and r['execution_model']==model and r['cost_ticks']==cost) for rule in RULES]
            tag=dict(execution_model=model,cost_ticks=cost,original_scenario=a['scenario'],quality_scenario=b['scenario'],delta_direction='QUALITY_MINUS_ORIGINAL')
            row=dict(tag)
            for metric in metrics:row.update({f'original_{metric}':a[metric],f'quality_{metric}':b[metric],f'delta_{metric}':b[metric]-a[metric]})
            row['ending_equity_ratio_quality_to_original']=b['balance_from_100']/a['balance_from_100']
            outputs['original_quality_head_to_head.csv'].append(row)
            for filename,outname,ids in [('monthly_results.csv','paired_monthly_deltas.csv',['month','start','end']),
                                         ('period_results.csv','paired_period_deltas.csv',['period','start','end']),
                                         ('rolling_windows.csv','paired_rolling_deltas.csv',['months','start','end'])]:
                mapping={tuple(r[k] for k in ids):r for r in outputs[filename] if r['scenario']==a['scenario']}
                quality={tuple(r[k] for k in ids):r for r in outputs[filename] if r['scenario']==b['scenario']}
                gates.check(f'paired_exact_intervals:{outname}:{model}:{cost}',set(mapping),set(quality))
                baseline={tuple(r[k] for k in ids):r for r in outputs[filename] if r['scenario']=='P31_BASELINE'}
                for identity,q in quality.items():
                    o=mapping[identity];base=baseline[identity]
                    fields=['return_pct','closed_window_dd_pct','candidate_entries','candidate_exits','candidate_pnl_cash','incumbent_pnl_cash']
                    delta=dict(tag,**dict(zip(ids,identity)))
                    for field in fields:
                        delta.update({f'baseline_{field}':base[field],f'original_{field}':o[field],f'quality_{field}':q[field],
                                      f'quality_minus_original_{field}':q[field]-o[field],f'original_minus_baseline_{field}':o[field]-base[field],f'quality_minus_baseline_{field}':q[field]-base[field]})
                    outputs[outname].append(delta)
    gates.require()

def portfolio_checks():
    tests=[]
    def verify(name,condition):
        if not condition:raise GateFailure('Portfolio synthetic failed: '+name)
        tests.append(dict(check=name,passed=True))
    def trade(sid,entry,exit,r,pair='EUR_USD'):
        return dict(sid=sid,entry=stamp(entry),exit=stamp(exit) if exit else None,r=r,pair=pair,side='BUY',tf='H1',rr=3.5,signal=stamp(entry-HOUR))
    t=date('2020-01-01T00:00:00Z')
    s=simulate_book([trade('A',t,t+HOUR,2),trade('B',t+HOUR,t+2*HOUR,-1)],'TEST')
    verify('exit_before_entry_same_time',[e['event'] for e in s['events'][1:3]]==['EXIT','ENTRY'])
    verify('compound_realized_equity_sizing',s['events'][2]['risk_cash']==1.02 and equal_price(s['summary']['balance_from_100'],100.98))
    special=simulate_book([trade('EUR_JPY_M15_SHORT',t,t+HOUR,-1,'EUR_JPY')],'TEST')
    verify('EURJPY_short_0p75pct',equal_price(special['summary']['balance_from_100'],99.25))
    opened=simulate_book([trade('OPEN',t,None,None,'EUR_CHF')],'TEST')
    verify('open_cash_unrealized',opened['summary']['balance_from_100']==100 and opened['summary']['trades']==0 and opened['summary']['open_at_cutoff']==1)
    verify('open_floor_and_grossCHF',equal_price(opened['summary']['max_open_risk_floor_dd_pct'],-1) and opened['summary']['max_gross_CHF_risk_pct']==1)
    gap=simulate_book([trade('GAP',t,t+HOUR,-2,'EUR_CHF')],'TEST')
    verify('gap_can_exceed_nominal_floor',gap['summary']['max_closed_dd_pct']<-1.99)
    verify('right_closed_exit_interval',interval_report(s,t,t+HOUR)['exit_count']==1)
    verify('entry_interval_left_closed_right_open',interval_report(s,t,t+HOUR)['entry_count']==1)
    verify('balance_all_tied_exits',balance_at(s,t+HOUR)==102)
    verify('six_positions_is_not_cap',simulate_book([trade(str(i),t,t+HOUR,-1) for i in range(7)],'TEST')['summary']['max_positions']==7)
    tied=simulate_book([trade('B',t,t+HOUR,-1),trade('A',t,t+HOUR,2)],'TEST')
    verify('lexical_exit_order',[e['sid'] for e in tied['events'] if e['event']=='EXIT']==['A','B'])
    identical=simulate_book([trade('SAME',t,t+HOUR,1),trade('SAME',t,t+HOUR,1)],'TEST')
    verify('stable_record_tie',[e['source_record_index'] for e in identical['events'][:2]]==[0,1])
    bars=[(date('2026-09-20T15:00:00Z'),1.002,1.003,.999,1.),(date('2026-09-20T16:00:00Z'),1.,1.001,.999,1.),
          (date('2026-09-20T17:00:00Z'),1.,1.001,.999,1.),(date('2026-09-20T18:00:00Z'),1.,1.001,.98,.99)]
    prefix=[b for b in bars if b[0]+HOUR<=CUTOFF]
    verify('forming_hour_excluded',len(prefix)==3 and prefix[-1][0].hour==17)
    path=isolated_path(prefix,0,'SCREEN_PARITY');future=isolated_path(bars,0,'SCREEN_PARITY')
    verify('future_target_not_realized',path['exit'] is None and future['exit'] is not None)
    record,invalid,blocked=execute_p0(RULES[0],[0],{0:path},'SCREEN_PARITY',10)
    verify('causal_open_R_blank',len(record)==1 and record[0]['r'] is None)
    second=isolated_path(prefix,1,'SCREEN_PARITY')
    a,_,b=execute_p0(RULES[0],[0,1],{0:path,1:second},'SCREEN_PARITY',10)
    verify('cutoff_open_keeps_p0_occupied',len(a)==1 and len(b)==1)
    dc=[(t,1.,1.,1.,1.,t+HOUR),(t+HOUR,1.,1.,1.,1.,t+2*HOUR)]
    indicators=([1.,1.],[1.,1.],{p:[1.,1.] for p in (150,200,250)})
    verify('developing_daily_unavailable',context_for_signal(dc,indicators,t+timedelta(minutes=59))['daily_index'] is None)
    verify('daily_exact_completion_available',context_for_signal(dc,indicators,t+HOUR)['daily_index']==0)
    verify('daily_future_not_selected',context_for_signal(dc,indicators,t+HOUR+timedelta(minutes=1))['daily_index']==0)
    verify('common_endpoints_all_scenarios',s['summary']['common_start']==stamp(BEGIN) and s['summary']['cutoff']==stamp(CUTOFF))
    verify('partial_month_not_complete_rolling',portfolio_months()[-1]==date('2026-09-01T00:00:00Z') and CUTOFF.day!=1)
    return tests

def software_checks():
    return _frozen_software_checks()+portfolio_checks()

def data_key():
    return digest(json.dumps(dict(reference=REFERENCE_SHA256,frozen=FROZEN,controls=ADMISSION_CONTROL_SHA256,
        baseline=BASELINE_SHA256,cutoff=stamp(CUTOFF),design=DESIGN_SHA256,costs=COSTS,models=MODELS),sort_keys=True).encode())


def confirmation_job():
    global FILE_LOCK
    gates=Gates(); success=False
    manifest=dict(version=VERSION,status='RUNNING',runner_sha256=runner_hash(),incumbent=PORTFOLIO_VERSION,
                  cutoff=stamp(CUTOFF),scenarios_expected=13,orders_supported=False,history_is_in_sample=True,
                  baseline_source_scope='Frozen accepted completed P31 book; no incumbent candle refresh',automatic_admission=False,
                  design_sha256=DESIGN_SHA256,admission_control_sha256=ADMISSION_CONTROL_SHA256,frozen_reference_sha256=REFERENCE_SHA256,compression_selected=False,quality_portfolio_admission_complete=False,candidate_risk_fraction=.01,quote_currency_conversion_model='Inherited dimensionless R accounting; no dynamic GBP translation')
    try:
        with tempfile.TemporaryDirectory(prefix='pass13-admission-',dir=OUT) as folder:
            work=Path(folder)
            (work/'protocol.md').write_text(PROTOCOL,encoding='utf-8')
            (work/'runner_source.py').write_bytes(Path(__file__).read_bytes())
            try:
                tests=software_checks(); dump_csv(work/'software_checks.csv',tests)
                write_status('running',progress=5,message='Verifying exact P31 and confirmed final strategy references',result_path=None)
                candles,daily,blobs,snapshot=load_sources(gates)
                controls=load_admission_controls(gates)
                coverage=audit_sources(candles,daily,gates)
                dump_json(work/'admission_design.json',DESIGN)
                dump_json(work/'admission_control_provenance.json',json.loads(controls['control_provenance.json']))
                incumbent=load_incumbents(gates)
                base=simulate_book(incumbent,'P31_BASELINE')
                for k,v in EXPECTED_BASELINE.items():
                    actual=base['summary'][k]
                    passed=math.isclose(actual,v,rel_tol=1e-12,abs_tol=1e-8) if isinstance(v,float) else actual==v
                    gates.rows.append(dict(check='P31_frozen_metric:'+k,passed=passed,expected=v,actual=actual))
                gates.check('P31_input_book_canonical_sha256',book_hash(incumbent),BASELINE_SHA256)
                gates.require()
                confirmed=confirm(candles,daily,blobs,gates)
                for name,records in confirmed.items(): dump_csv(work/('frozen_confirmation_'+name),records)
                cutoff_source=build_cutoff_source(candles,daily,gates)
                dump_csv(work/'candidate_raw_cutoff_memberships.csv',cutoff_source['memberships'])
                dump_csv(work/'candidate_cutoff_daily_context.csv',cutoff_source['contexts'])
                dump_csv(work/'daily_coverage_audit.csv',coverage)
                outputs=defaultdict(list)
                outputs['full_history_confirmation_summary.csv']=confirmed['summary.csv']
                outputs['full_history_candidate_ledgers.csv']=confirmed['accepted_trades.csv']
                bounds=portfolio_months()
                base_tag=dict(scenario='P31_BASELINE',role='BASELINE',strategy_id='',rr=None,execution_model='INCUMBENT_FROZEN',cost_ticks=None)
                bm,bp,br,bs=portfolio_reports(base,base_tag)
                base_summary=dict(base_tag,**{k:v for k,v in base['summary'].items() if k!='scenario'})
                for width in (12,24,36):
                    x=next(r for r in bs if r['months']==width); base_summary[f'worst_{width}m_return_pct']=x['worst_return_pct']
                base_summary.update(delta_common_cagr_pp=0.0,delta_closed_dd_pp=0.0,delta_floor_dd_pp=0.0,delta_max_positions=0,
                                    delta_max_open_risk_pp=0.0,direct_candidate_pnl_cash=0.0,incumbent_resizing_delta_cash=0.0,delta_ending_equity=0.0,candidate_qualified_at_cutoff=0,candidate_accepted_entries=0,candidate_p0_blocked=0,
                                    candidate_invalid_unblocked=0,candidate_cutoff_ledger_sha256=None,cutoff_completed_candles=None)
                outputs['portfolio_summary.csv'].append(base_summary)
                outputs['event_ties.csv'] += event_ties(base,base_tag)
                outputs['scenario_plan.csv'].append(dict(base_tag,candidate_risk_fraction=None,incumbent_risk_map='1% except EUR_JPY_M15_SHORT0.75%',global_position_cap=None,cutoff=stamp(CUTOFF)))
                outputs['equity_events.csv'] += base['events']
                outputs['monthly_results.csv'] += bm; outputs['period_results.csv'] += bp; outputs['rolling_windows.csv'] += br; outputs['rolling_summary.csv'] += bs
                windows=[('BASELINE_DEEPEST_CLOSED_DD',date(base['summary']['dd_peak']),date(base['summary']['dd_trough']))]
                windows += [(f'BASELINE_WORST_{r["months"]}M',date(r['worst_start']),date(r['worst_end'])) for r in bs]
                outputs['weak_window_attribution.csv'] += window_attribution(base,base,windows,base_tag)
                for rule in RULES:
                    if rule['role']=='QUALITY_ALTERNATIVE':
                        gate_original_admission(outputs,controls,gates)
                        manifest['reviewed_original_Pass8_complete_controls_pass']=True
                    for model in MODELS:
                        for cost in COSTS:
                            name=f'P32_{rule["role"]}_{model}_{cost}T'
                            tag=dict(scenario=name,role=rule['role'],strategy_id=rule['strategy_id'],rr=rule['rr'],execution_model=model,cost_ticks=cost)
                            candidate,records,audit,prefix_count,blocked=cutoff_candidates(cutoff_source,rule,model,cost,confirmed['accepted_trades.csv'],gates)
                            combined=incumbent+candidate
                            gates.check(name+':incumbents_preserved_exact',combined[:len(incumbent)]==incumbent,True)
                            gates.check(name+':incumbent_book_hash',book_hash(combined[:len(incumbent)]),BASELINE_SHA256)
                            gates.require()
                            sim=simulate_book(combined,name)
                            outputs['incumbent_resizing.csv'] += resizing_rows(sim,base,tag,gates)
                            outputs['event_ties.csv'] += event_ties(sim,tag)
                            outputs['candidate_blocked_signals.csv'] += [dict(tag,**r) for r in cutoff_source['last_blocked']]
                            outputs['candidate_invalid_entries.csv'] += [dict(tag,**r) for r in cutoff_source['last_invalid']]
                            monthly,period,rolling,rollsum=portfolio_reports(sim,tag)
                            summary=dict(tag,**{k:v for k,v in sim['summary'].items() if k!='scenario'})
                            for width in (12,24,36):
                                row=next(r for r in rollsum if r['months']==width)
                                summary[f'worst_{width}m_return_pct']=row['worst_return_pct']
                            newcash=sum(e['pnl_cash'] for e in sim['events'] if e['source']=='CANDIDATE')
                            oldcash=sum(e['pnl_cash'] for e in sim['events'] if e['source']=='INCUMBENT')
                            baselinesum=sum(e['pnl_cash'] for e in base['events'])
                            summary.update(delta_common_cagr_pp=summary['common_window_cagr_pct']-base_summary['common_window_cagr_pct'],
                                           delta_closed_dd_pp=summary['max_closed_dd_pct']-base_summary['max_closed_dd_pct'],
                                           delta_floor_dd_pp=summary['max_open_risk_floor_dd_pct']-base_summary['max_open_risk_floor_dd_pct'],
                                           delta_max_positions=summary['max_positions']-base_summary['max_positions'],delta_max_open_risk_pp=summary['max_open_risk_pct']-base_summary['max_open_risk_pct'],
                                           direct_candidate_pnl_cash=newcash,incumbent_resizing_delta_cash=oldcash-baselinesum,
                                           delta_ending_equity=summary['balance_from_100']-base_summary['balance_from_100'],
                                           candidate_qualified_at_cutoff=len(audit),candidate_accepted_entries=len(records),candidate_p0_blocked=blocked,
                                           candidate_invalid_unblocked=sum(r['status'] not in ('ACCEPTED_OPEN','ACCEPTED_CLOSED','BLOCKED_P0') for r in audit),
                                           candidate_cutoff_ledger_sha256=ledger_hash(records),cutoff_completed_candles=prefix_count)
                            gates.check(name+':cash_delta_identity',equal_price(summary['delta_ending_equity'],newcash+oldcash-baselinesum),True)
                            outputs['portfolio_summary.csv'].append(summary)
                            outputs['scenario_plan.csv'].append(dict(tag,candidate_risk_fraction=.01,incumbent_risk_map='1% except EUR_JPY_M15_SHORT0.75%',global_position_cap=None,cutoff=stamp(CUTOFF)))
                            outputs['candidate_cutoff_ledgers.csv'] += [dict(tag,**{k:v for k,v in r.items() if k not in tag}) for r in records]
                            outputs['candidate_gate_audit.csv'] += [dict(tag,**r) for r in audit]
                            outputs['open_at_portfolio_cutoff.csv'] += [dict(tag,**{k:v for k,v in r.items() if k not in tag}) for r in sim['open_positions']]
                            outputs['entry_overlap.csv'] += entry_overlaps(candidate,incumbent,tag)
                            outputs['equity_events.csv'] += sim['events']
                            outputs['monthly_results.csv'] += monthly; outputs['period_results.csv'] += period; outputs['rolling_windows.csv'] += rolling; outputs['rolling_summary.csv'] += rollsum
                            own=[('SCENARIO_DEEPEST_CLOSED_DD',date(summary['dd_peak']),date(summary['dd_trough']))]
                            own += [(f'SCENARIO_WORST_{r["months"]}M',date(r['worst_start']),date(r['worst_end'])) for r in rollsum]
                            outputs['weak_window_attribution.csv'] += window_attribution(sim,base,windows+own,tag)
                            write_status('running',progress=35+int(55*(len(outputs['portfolio_summary.csv'])-1)/12),message=f'{len(outputs["portfolio_summary.csv"])-1}/12 frozen candidate additions replayed',result_path=None)
                add_comparison_reports(outputs,gates)
                gates.check('exact_admission_scenario_count',len(outputs['portfolio_summary.csv']),13)
                gates.check('exact_complete_rolling_windows',len(outputs['rolling_windows.csv']),9243)
                gates.require()
                for empty,fields in EMPTY_FIELDS.items():
                    if not outputs[empty]: dump_csv(work/empty,[],fields)
                for n,r in outputs.items():
                    if r or n not in EMPTY_FIELDS: dump_csv(work/n,r)
                if not outputs['open_at_portfolio_cutoff.csv']:
                    dump_csv(work/'open_at_portfolio_cutoff.csv',[],['scenario','sid','entry','exit','risk_cash','r'])
                (work/'incumbent_frozen_book.json').write_bytes(base64.b85decode(BASELINE_B85))
                dump_json(work/'baseline_expected.json',dict(incumbent=PORTFOLIO_VERSION,cutoff=stamp(CUTOFF),ledger_sha256=BASELINE_SHA256,
                    expected_metrics=EXPECTED_BASELINE,risk_map='1% except EUR_JPY_M15_SHORT0.75%',global_position_cap=None,
                    accepted_book_sufficient_reason='No EUR_CHF incumbents; no shared global cap; AUDJPY gate unaffected',
                    source_scope='Exact frozen archived completed book; no fresh incumbent candle rebuild'))
                dump_csv(work/'incumbent_frozen_book.csv',incumbent)
                dump_csv(work/'incumbent_registry.csv',[dict(sid=sid,risk_fraction=risk_rate(sid),trades=sum(r['sid']==sid for r in incumbent)) for sid in sorted({r['sid'] for r in incumbent})])
                (work/'frozen_definitions.json').write_bytes(blobs['frozen_definitions.json'])
                (work/'source_candles.csv').write_bytes(blobs['source_candles.csv'])
                (work/'daily_snapshot.json').write_bytes(blobs['daily_snapshot.json'])
                dump_json(work/'source_pins.json',FROZEN['source'])
                dump_json(work/'reference_integrity.json',dict(frozen_reference_sha256=REFERENCE_SHA256,admission_controls_sha256=ADMISSION_CONTROL_SHA256,design_sha256=DESIGN_SHA256))
                dump_csv(work/'daily_cutoff_intervals.csv',[dict(time=stamp(b[0]),end=stamp(b[5])) for b in cutoff_source['daily']])
                dump_csv(work/'coverage.csv',[dict(source='EURCHF_CONFIRMED',candles=len(candles),source_sha256=FROZEN['source']['H1_canonical_OHLC_sha256'],standalone_end_exclusive=stamp(FINISH),
                                                  admission_cutoff=stamp(CUTOFF),admission_completed_candles=prefix_count,admission_last_completed_open=stamp(candles[prefix_count-1][0]),
                                                  incumbent_source_sha256=BASELINE_SHA256,incumbent_records=3332,incumbent_rebuilt_from_candles=False)])
                manifest.update(status='COMPLETE',scenarios=13,baseline_controls_pass=True,full_candidate_parity_pass=True,cutoff_candidate_causality_pass=True,
                                software_checks=len(tests),parity_checks=len(gates.rows),output_row_counts={k:len(v) for k,v in outputs.items()},
                                admission_decision='AWAIT_REVIEW_NO_AUTOMATIC_ADMISSION',portfolio_admission_review_complete=False)
                success=True
            except Exception as exc:
                manifest.update(status='ERROR',error=str(exc),admission_decision='FAILED_GATE_NO_INTERPRETATION')
                dump_json(work/'error_report.json',dict(error=str(exc),traceback=traceback.format_exc()))
            dump_csv(work/'parity_checks.csv',gates.rows,['check','passed','expected','actual'])
            manifest['completed_utc']=stamp(datetime.now(UTC)); dump_json(work/'run_manifest.json',manifest)
            publish(work,success)
            write_status('complete' if success else 'error',progress=100,frozen_data_key=data_key(),manifest=manifest,result_path=RESULT_NAME,result_sha256=digest((OUT/RESULT_NAME).read_bytes()),
                         message='Exact frozen P31 admission scenarios complete; review required' if success else 'Failed gate; download error ZIP')
    except Exception as exc:
        success=False; write_status('error',progress=100,frozen_data_key=data_key(),result_path=None,message='Publication failed: '+str(exc))
    finally:
        if FILE_LOCK is not None:
            FILE_LOCK.close(); FILE_LOCK=None
    return success

def read_status():
    try:
        return json.loads((OUT/'status.json').read_text())
    except (OSError,ValueError):
        return dict(state='idle',version=VERSION)

def write_status(state,**values):
    OUT.mkdir(parents=True,exist_ok=True)
    record=dict(state=state,version=VERSION,runner_sha256=runner_hash(),updated=stamp(datetime.now(UTC)),**values)
    with tempfile.NamedTemporaryFile(dir=OUT,mode='w',encoding='utf-8',delete=False) as f:
        json.dump(record,f,allow_nan=False)
        temporary=f.name
    os.replace(temporary,OUT/'status.json')

def publish(work,success):
    diagnostics={'protocol.md','run_manifest.json','error_report.json','parity_checks.csv',
                 'software_checks.csv','runner_source.py','admission_design.json'}
    members=[p for p in sorted(work.iterdir()) if p.is_file() and p.name!='file_manifest.json'
             and (success or p.name in diagnostics)]
    dump_json(work/'file_manifest.json',[dict(file=p.name,bytes=p.stat().st_size,sha256=digest(p.read_bytes())) for p in members])
    fd,temporary=tempfile.mkstemp(dir=OUT,suffix='.zip');os.close(fd)
    try:
        with zipfile.ZipFile(temporary,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as archive:
            for member in members+[work/'file_manifest.json']:
                archive.write(member,member.name)
        os.replace(temporary,OUT/RESULT_NAME)
    finally:
        if os.path.exists(temporary):os.unlink(temporary)

def launch(background=True):
    global STARTED,FILE_LOCK
    with MUTEX:
        if STARTED:return False
        OUT.mkdir(parents=True,exist_ok=True)
        if os.name=='posix':
            import fcntl
            handle=(OUT/'run.lock').open('a+')
            try:fcntl.flock(handle,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError:handle.close();return False
            FILE_LOCK=handle
        prior=read_status();bundle=OUT/RESULT_NAME
        if (prior.get('state')=='complete' and prior.get('runner_sha256')==runner_hash()
            and prior.get('frozen_data_key')==data_key() and bundle.exists()
            and digest(bundle.read_bytes())==prior.get('result_sha256')):
            STARTED=True
            if FILE_LOCK is not None:FILE_LOCK.close();FILE_LOCK=None
            return False
        STARTED=True
        write_status('starting',progress=0,result_path=None,message='Exact frozen P31 original versus ATR1.50 portfolio comparison')
    if background:
        threading.Thread(target=confirmation_job,name='eurchf-pass13',daemon=True).start()
        return True
    return confirmation_job()

def app(environ,start_response):
    path=environ.get('PATH_INFO','/')
    if path==PREFIX or path.startswith(PREFIX+'/'):path=path[len(PREFIX):] or '/'
    method=environ.get('REQUEST_METHOD','GET')
    code='200 OK'
    if method not in ('GET','HEAD'):
        code,value='405 Method Not Allowed',dict(error='GET or HEAD only')
    elif path not in ('/','/start','/status','/health','/results'):
        code,value='404 Not Found',dict(error='Not found')
    else:
        if method=='GET' and (path=='/start' or os.getenv('EURCHF_PASS13_AUTOSTART','1')=='1') and not STARTED:
            launch()
        value=read_status()
        if path=='/results':
            bundle=OUT/RESULT_NAME
            current=(value.get('state') in ('complete','error') and value.get('runner_sha256')==runner_hash()
                     and value.get('frozen_data_key')==data_key() and value.get('result_path')==RESULT_NAME
                     and bundle.exists() and digest(bundle.read_bytes())==value.get('result_sha256'))
            if current:
                start_response(code,[('Content-Type','application/zip'),('Content-Length',str(bundle.stat().st_size)),
                    ('Content-Disposition',f'attachment; filename="{RESULT_NAME}"'),('Cache-Control','no-store')])
                if method=='HEAD':return []
                def blocks():
                    with bundle.open('rb') as f:
                        while True:
                            block=f.read(1024*1024)
                            if not block:break
                            yield block
                return blocks()
            code='409 Conflict';value=dict(value,error='Results not ready for this exact code and frozen source')
        elif path=='/health':value=dict(ok=True,state=value.get('state'),version=VERSION,orders_supported=False)
        elif path=='/':value=dict(service='EUR/CHF frozen P31 portfolio comparison',
                                 version=VERSION,state=value.get('state'),status='/status',results='/results',orders_supported=False)
    body=(json.dumps(value,allow_nan=False)+'\n').encode()
    start_response(code,[('Content-Type','application/json'),('Content-Length',str(len(body))),('Cache-Control','no-store')])
    return [] if method=='HEAD' else [body]

class ConcurrentServer(ThreadingMixIn,WSGIServer):
    daemon_threads=True

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    group=parser.add_mutually_exclusive_group()
    group.add_argument('--run',action='store_true')
    group.add_argument('--self-test',action='store_true')
    args=parser.parse_args()
    if args.self_test:
        print(json.dumps(dict(version=VERSION,market_data_used=False,checks=software_checks()),indent=2));return 0
    if args.run:
        launch(background=False);print(json.dumps(read_status(),indent=2))
        return 0 if read_status().get('state')=='complete' else 1
    if os.getenv('EURCHF_PASS13_AUTOSTART','1')=='1':launch()
    with make_server('0.0.0.0',int(os.getenv('PORT','8080')),app,server_class=ConcurrentServer) as server:
        print(VERSION+': /status and /results',flush=True);server.serve_forever()
    return 0

if __name__=="__main__":
    raise SystemExit(main())
